async function retry(fn, times = 3, waitMs = 100) {
  let lastError;
  for (let i = 0; i < times; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (i < times - 1) await new Promise((r) => setTimeout(r, waitMs));
    }
  }
  throw lastError;
}

