async function retryOnNetworkError(fn, attempts = 3) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (!(err instanceof TypeError)) throw err;
    }
  }
  throw lastErr;
}

