function promisePool(items, workerCount, worker) {
  const results = new Array(items.length);
  let next = 0;
  async function run() {
    while (next < items.length) {
      const i = next++;
      results[i] = await worker(items[i], i);
    }
  }
  const workers = Array.from({ length: Math.min(workerCount, items.length) }, run);
  return Promise.all(workers).then(() => results);
}

