async function cachedFetch(url, cache) {
  if (cache.has(url)) return cache.get(url);
  const promise = fetch(url)
    .then((res) => res.json())
    .catch((err) => {
      cache.delete(url);
      throw err;
    });
  cache.set(url, promise);
  return promise;
}

